const PLABELS={
company:'Company',name:'Contact person',email:'Email',phone:'Mobile / Viber',clientref:'Partner reference',
qtype:'Quotation type',package:'Package',destination:'Destination / route',start:'Travel date',end:'Until',flexible:'Flexible dates',
adults:'Adults',children:'Children',foc:'Tour leaders / FOC',twin:'Twin rooms',single:'Single rooms',triple:'Triple rooms',
hotel:'Hotel class',meals:'Meals',include:'Include in quotation',basis:'Rate basis',currency:'Currency',needby:'Quote needed by',
budget:'Target budget per pax',market:'Client market',notes:'Other requirements'
};
const P_DATES=['start','end','needby'];
const pField=(k,v)=>(P_DATES.indexOf(k)===-1?String(v==null?'':v):fmtISO(v));
const normCode=v=>String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
async function partnerFor(raw){
const n=normCode(raw);
if(n.length<6||!(window.crypto&&crypto.subtle&&window.TextEncoder))return null;
const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('icp:'+n));
const h=Array.from(new Uint8Array(buf),x=>x.toString(16).padStart(2,'0')).join('');
const hit=(CONFIG.partnerCodes||[]).find(c=>c.h===h);
return hit?{type:hit.type,code:String(raw).trim().toUpperCase().replace(/\s+/g,'-')}:null;
}
function buildPartnerDoc(o,partner,ref,issued){
const n=k=>paxCount(o[k])||0;
const heads=n('adults')+n('children')+n('foc');
const group=[n('adults')&&`${n('adults')} adult${n('adults')===1?'':'s'}`,n('children')&&`${n('children')} child${n('children')===1?'':'ren'}`,n('foc')&&`${n('foc')} tour leader / FOC`].filter(Boolean).join(', ');
const rooms=[n('twin')&&`${n('twin')} twin`,n('single')&&`${n('single')} single`,n('triple')&&`${n('triple')} triple`].filter(Boolean).join(', ');
const dates=[fmtISO(o.start),o.end?fmtISO(o.end):''].filter(Boolean).join(' – ')+(o.flexible?' (flexible)':'');
const subject=o.package&&o.package!=='Not decided yet'?o.package:(o.destination||o.qtype);
const facts=[
['Travel dates',dates||'To be advised'],
['Group',heads?`${heads} pax${group?' ('+group+')':''}`:'To be advised'],
['Rooms',rooms],
['Hotel',o.hotel],
['Meals',o.meals]
].filter(r=>r[1]).map(r=>`<dt>${r[0]}</dt><dd>${esc(r[1])}</dd>`).join('');
const reqKeys=['destination','include','basis','currency','budget','needby','market','clientref'];
const rows=reqKeys.filter(k=>o[k]&&!(k==='destination'&&o[k]===subject))
.map(k=>`<tr><td class="k">${PLABELS[k]}</td><td class="v">${esc(pField(k,o[k]))}</td></tr>`).join('');
return`
    <div class="qt-doc" id="qtDoc">
      <div class="qt-band"></div>
      <header class="qt-head">
        <div class="qt-brand">
          <img src="${IC.media?IC.media.mark:''}" alt="">
          <div>
            <strong>Immaculate Connections</strong>
            <span class="tag">Travel Agency &middot; Partner desk</span>
            <span>${esc(CONFIG.address)}</span>
            <span>${esc(CONFIG.mobile)} &middot; ${esc(CONFIG.landline)}</span>
            <span>${esc(CONFIG.email)}</span>
          </div>
        </div>
        <div class="qt-meta">
          <div class="qt-title">Quotation request</div>
          <dl>
            <dt>Request no.</dt><dd class="ref">${esc(ref)}</dd>
            <dt>Date sent</dt><dd>${esc(fmtDate(issued))}</dd>
            <dt>Partner</dt><dd>${esc(partner.type)}</dd>
            <dt>Status</dt><dd><span class="qt-status">Rates to follow</span></dd>
          </dl>
        </div>
      </header>
      <div class="qt-subject">
        <span class="qt-label">B2B quotation request for</span>
        <h3>${esc(subject)}</h3>
        <p>${esc([o.qtype,dates,heads?heads+' pax':''].filter(Boolean).join(' · '))}</p>
      </div>
      <div class="qt-parties">
        <div>
          <span class="qt-label">Requested by</span>
          <strong>${esc(o.company||'')}</strong>
          <p>${esc(o.name||'')}<br>${esc(o.email||'')}${o.phone?'<br>'+esc(o.phone):''}<br>Partner code ${esc(partner.code)}</p>
        </div>
        <div>
          <span class="qt-label">Group summary</span>
          <dl class="qt-facts">${facts}</dl>
        </div>
      </div>
      ${rows?`<div class="qt-section"><h4>Requirements</h4><table class="qt-table"><tbody>${rows}</tbody></table></div>`:''}
      ${String(o.notes||'').trim()?`<div class="qt-section"><h4>Notes from you</h4><p class="qt-quote">${esc(o.notes)}</p></div>`:''}
      <div class="qt-section qt-notes">
        <h4>What happens next</h4>
        <div class="qt-callout">${I.mail}<p><strong>Our team replies to ${esc(o.email||'your email address')}</strong> with the partner quotation once availability is checked with our hotel, transport and airline partners. Quote <strong>${esc(ref)}</strong> in any follow-up.</p></div>
        <ol>
          <li>This is a <strong>request</strong>, not a quotation or a booking. Rates, rooms and seats are not held until our team confirms them in writing.</li>
          <li>Rates are quoted on the basis you asked for (${esc(o.basis||'net rate')}, ${esc(o.currency||'PHP')}) and are subject to availability and peak-date surcharges.</li>
          <li><strong>No payment is collected on this website.</strong> Payment terms come with the confirmed partner quotation.</li>
        </ol>
      </div>
      <footer class="qt-foot">
        <div class="sig">
          <span class="qt-label">Received by</span>
          <strong>Reservations Team</strong>
          <span>Immaculate Connections Travel Agency</span>
          <span>${esc(CONFIG.email)} &middot; ${esc(CONFIG.mobile)}</span>
        </div>
        <div class="stamp">
          <span>Request no.</span>
          <strong>${esc(ref)}</strong>
          <em>Sent ${esc(fmtDate(issued))}</em>
        </div>
      </footer>
      <p class="qt-legal"><strong>This document is a copy of a quotation request, not a quotation, an invoice or a receipt.</strong> Thank you for partnering with Immaculate Connections Travel Agency.</p>
    </div>`;
}
function initPartner(){
const pf=$('#partnerForm'),cf=$('#partnerCodeForm'),tf=$('#inquiryForm');
if(!pf||!cf||!tf)return;
const tabs=$$('.inq-tab'),tabP=tabs.find(t=>t.dataset.mode==='partner');
const badge=$('#partnerBadge'),msg=$('#pcodeMsg'),input=$('#f_pcode');
const MSG=msg.textContent,KEY='icPartnerCode',DAYS30=30*864e5;
let partner=null,tries=0;
const keep=v=>{try{if(v)localStorage.setItem(KEY,JSON.stringify({c:v,t:Date.now()}));else localStorage.removeItem(KEY);sessionStorage.removeItem(KEY);}catch(_){}};
const kept=()=>{
try{
const o=JSON.parse(localStorage.getItem(KEY)||'null');
if(o&&o.c&&Date.now()-o.t<DAYS30)return o.c;
localStorage.removeItem(KEY);
return sessionStorage.getItem(KEY);
}catch(_){return null;}
};
const say=(text,cls)=>{msg.textContent=text;msg.className='pcode-msg'+(cls?' '+cls:'');};
const pkg=$('#p_package',pf);
if(pkg&&IC.tours){
pkg.innerHTML='<option value="">Not decided yet</option>'+
countryList().map(c=>{
const list=IC.tours.filter(t=>cSlug(t.country)===c.slug&&effStatus(t)!=='past');
return list.length?`<optgroup label="${esc(c.name)}">${list.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}${t.duration?' · '+esc(t.duration):''}</option>`).join('')}</optgroup>`:'';
}).join('');
}
const showType=()=>{
const v=(pf.elements.qtype&&pf.elements.qtype.value)||'';
$$('[data-pfor]',pf).forEach(el=>{const ok=el.dataset.pfor===v;el.hidden=!ok;$$('input,select',el).forEach(f=>{f.disabled=!ok;});});
};
$$('input[name="qtype"]',pf).forEach(r=>r.addEventListener('change',showType));
showType();
if(pkg)pkg.addEventListener('change',()=>{
const t=IC.tours.find(x=>x.id===pkg.value),d=$('#p_dest',pf);
if(t&&d&&!d.value.trim())d.value=t.places.slice(0,4).join(', ');
});
let mode='traveller';
const setMode=m=>{
mode=m==='partner'?'partner':'traveller';
const p=mode==='partner';
tabs.forEach(t=>{const on=t.dataset.mode===mode;t.classList.toggle('is-on',on);t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;});
tf.hidden=p;pf.hidden=!(p&&partner);cf.hidden=!(p&&!partner);badge.hidden=!(p&&partner);
document.body.classList.toggle('partner-mode',p);
};
const paint=()=>{
tabP.classList.toggle('is-unlocked',!!partner);
$('[data-ptab-sub]',tabP).innerHTML=partner?esc(partner.type):'B2B &middot; partner code required';
if(partner){
$$('[data-partner-type]').forEach(el=>{el.textContent=partner.type;});
$$('[data-partner-code]').forEach(el=>{el.textContent=partner.code;});
}
};
const unlock=(hit,focus)=>{
partner=hit;keep(hit.code);paint();setMode('partner');
if(focus){
const top=pf.getBoundingClientRect().top+window.scrollY-180;
window.scrollTo({top,behavior:reduced?'auto':'smooth'});
if(!touch)$('#p_company',pf).focus({preventScroll:true});
}
};
cf.addEventListener('submit',async e=>{
e.preventDefault();
if(!normCode(input.value)){say('Type the partner code our team sent you, for example IC-XXXX-XXXX.','bad');input.focus();return;}
if(tries>=8){say('Too many attempts. Please message or call us for your partner code.','bad');return;}
if(!(window.crypto&&crypto.subtle)){say('This browser cannot check partner codes. Please message us and we will send the partner form.','bad');return;}
const hit=await partnerFor(input.value);
if(!hit){
tries++;
input.setAttribute('aria-invalid','true');
say('That code did not match. Check it with our team, or switch to Traveller inquiry.','bad');
cf.classList.remove('shake');void cf.offsetWidth;cf.classList.add('shake');
return;
}
input.value='';input.removeAttribute('aria-invalid');say(MSG);
unlock(hit,true);prefill();
});
input.addEventListener('input',()=>{if(input.getAttribute('aria-invalid')){input.removeAttribute('aria-invalid');say(MSG);}});
tabs.forEach(t=>t.addEventListener('click',()=>{
setMode(t.dataset.mode);
if(mode==='partner'&&!partner&&!touch)input.focus({preventScroll:true});
}));
$('.inq-mode').addEventListener('keydown',e=>{
if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;
const i=tabs.indexOf(document.activeElement);if(i<0)return;
e.preventDefault();const nx=tabs[(i+1)%tabs.length];nx.focus();nx.click();
});
$('#partnerSignOut').addEventListener('click',()=>{
partner=null;keep(null);paint();setMode('partner');say(MSG);input.focus();
});
const params=new URLSearchParams(location.search);
const fromLink=params.get('partner');
if(fromLink){params.delete('partner');history.replaceState(null,'',location.pathname+(params.toString()?'?'+params:'')+location.hash);}
const start=fromLink||kept();
const fromPkg=IC.tours&&IC.tours.find(t=>t.id===params.get('package')&&effStatus(t)!=='past');
const prefill=()=>{
if(!fromPkg)return;
const set=(sel,v)=>{const el=$(sel,pf);if(el&&v!=null&&v!==''&&!el.value){el.value=v;el.dispatchEvent(new Event('change',{bubbles:true}));}};
const tp=$('input[name="qtype"][value="Tour package"]',pf);if(tp&&!tp.checked){tp.checked=true;showType();}
if(pkg){pkg.value=fromPkg.id;}
set('#p_dest',(fromPkg.places||[]).slice(0,4).join(', ')||fromPkg.country);
const d=params.get('date');
if(/^\d{4}-\d{2}-\d{2}$/.test(d||'')){
set('#p_start',d);
const endP=params.get('end');
if(/^\d{4}-\d{2}-\d{2}$/.test(endP||'')&&endP>=d)set('#p_end',endP);
else if(fromPkg.days>1){const e=new Date(d+'T00:00:00');e.setDate(e.getDate()+fromPkg.days-1);set('#p_end',`${e.getFullYear()}-${String(e.getMonth()+1).padStart(2,'0')}-${String(e.getDate()).padStart(2,'0')}`);}
}
const cur=fromPkg.price&&fromPkg.price.currency;if(cur){const c=$('#p_cur',pf);if(c)c.value=cur.toUpperCase();}
set('#p_notes',params.get('notes')||`Partner rate request for the ${fromPkg.name}.`);
};
if(start)partnerFor(start).then(hit=>{
if(hit&&(fromLink||fromPkg)){unlock(hit,true);prefill();}
else if(hit){partner=hit;paint();}
else{keep(null);if(fromLink){setMode('partner');say('The partner code in that link did not match. Type it below, or message us.','bad');}}
});
const end=$('#p_end',pf),startD=$('#p_start',pf);
const checkEnd=()=>end.setCustomValidity(end.value&&startD.value&&end.value<startD.value?'Must be on or after the travel date.':'');
[end,startD].forEach(el=>el.addEventListener('change',checkEnd));
pf.addEventListener('submit',async e=>{
e.preventDefault();
if(!partner){setMode('traveller');return;}
checkEnd();
let first=null;
$$('.field',pf).forEach(f=>f.classList.remove('error'));
$$('input,select,textarea',pf).forEach(el=>{
if(el.disabled||el.name==='_honey'||el.checkValidity())return;
const f=el.closest('.field');if(f)f.classList.add('error');if(!first)first=el;
});
if(first){first.focus();return;}
const fd=new FormData(pf),o={};
if(fd.get('_honey'))return;
fd.forEach((v,k)=>{if(v===''||k==='consent'||k.startsWith('_'))return;o[k]=o[k]?o[k]+', '+v:v;});
if(o.package&&IC.tours){const t=IC.tours.find(x=>x.id===o.package);o.package=t?t.name+(t.duration?` (${t.duration})`:''):o.package;}
const btn=$('[type="submit"]',pf),errBox=$('#pError',pf);
errBox.classList.remove('show');btn.disabled=true;btn.textContent='Sending your request…';
const ref=quoteRef(CONFIG.partnerPrefix),issued=new Date();
const lines=Object.keys(PLABELS).filter(k=>o[k]).map(k=>`${PLABELS[k]}: ${pField(k,o[k])}`).join('\n');
const first1=(o.name||'').split(' ')[0]||'there';
const payload={
_subject:`Partner quotation request ${ref}: ${o.company} – ${o.qtype}${o.package?' – '+o.package:''}`,
_template:'table',_captcha:'false',_replyto:o.email,
_autoresponse:`Hi ${first1},\n\nThank you for your partner quotation request with Immaculate Connections Travel Agency. Here is a copy for your records.\n\nREQUEST ${ref}\nSent: ${fmtDate(issued)}\nPartner: ${partner.type} (code ${partner.code})\n\n${lines}\n\nWHAT HAPPENS NEXT\nOur team checks availability with our partners and replies to this address with the partner quotation. Rates are not held until confirmed in writing, and nothing is collected through the website.\n\nImmaculate Connections Travel Agency\n${CONFIG.address}\nMobile ${CONFIG.mobile} · Tel ${CONFIG.landline}\n${CONFIG.email}`,
'Request ref':ref,'Partner type':partner.type,'Partner code':partner.code
};
Object.keys(PLABELS).forEach(k=>{if(o[k])payload[PLABELS[k]]=pField(k,o[k]);});
payload['Sent from']=location.href;
let sent=false;
try{
const r=await fetch(CONFIG.formEndpoint,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(payload)});
const j=await r.json().catch(()=>({}));sent=r.ok&&String(j.success)!=='false';
}catch(_){sent=false;}
btn.disabled=false;btn.innerHTML='Send quotation request '+I.arrow;
const ok=$('#pSuccess',pf);
const text=`Partner quotation request ${ref}\nPartner: ${partner.type} (code ${partner.code})\n\n${lines}`;
const mail=$('#pMail',ok),msgL=$('#pMsg',ok);
mail.href=`mailto:${CONFIG.email}?subject=${encodeURIComponent(`Partner quotation request ${ref}: ${o.company}`)}&body=${encodeURIComponent(text)}`;
msgL.href=CONFIG.messenger;
$('#pDoc',ok).innerHTML=buildPartnerDoc(o,partner,ref,issued);
$('#pBody',pf).style.display='none';
const h3=$('.qt-intro h3',ok),chk=$('.qt-intro .check',ok);
if(sent){
h3.textContent='Quotation request sent';
chk.classList.remove('pending');chk.innerHTML=I.check;
$('#pSuccessMsg',ok).textContent=`Thank you, ${first1}. Request ${ref} is with our team and a copy is on its way to ${o.email}. We reply with the partner quotation by email.`;
mail.className='btn btn-blue';mail.textContent='Email a copy';
}else{
h3.textContent='One more tap to send it';
chk.classList.add('pending');chk.innerHTML=I.mail;
$('#pSuccessMsg',ok).textContent=`Request ${ref} is ready, ${first1}, but our online form could not deliver it. Send it by email or Messenger with one tap; it reaches the same team.`;
mail.className='btn btn-primary';mail.textContent='Send by email';
}
ok.classList.add('show');
window.scrollTo({top:pf.getBoundingClientRect().top+window.scrollY-110,behavior:reduced?'auto':'smooth'});
});
$('#pDownload',pf).addEventListener('click',()=>window.print());
$('#pAgain',pf).addEventListener('click',()=>{
const keepCo=['company','name','email','phone'].map(k=>[k,pf.elements[k].value]);
pf.reset();keepCo.forEach(([k,v])=>{pf.elements[k].value=v;});
showType();
$('#pSuccess',pf).classList.remove('show');$('#pBody',pf).style.display='';
window.scrollTo({top:pf.getBoundingClientRect().top+window.scrollY-180,behavior:reduced?'auto':'smooth'});
});
}
function initPageHeroes(){
const hero=$('.page-hero, .pkg-hero');if(!hero)return;
const rig=$('.ph-rig',hero);if(!rig)return;
const scenes=$$('.ph-scene',rig),place=$('.ph-place-name',hero),DWELL=6000;
const MOVES={
push:['scale(1.06) translate3d(0, 0, 0)','scale(1.18) translate3d(-1.5%, 1%, 0)'],
dolly:['scale(1.04) translate3d(0, 1%, 0)','scale(1.26) translate3d(0, -1%, 0)'],
panR:['scale(1.15) translate3d(-3.5%, 0, 0)','scale(1.15) translate3d(3.5%, -.5%, 0)'],
panL:['scale(1.15) translate3d(3.5%, 0, 0)','scale(1.15) translate3d(-3.5%, .5%, 0)'],
pull:['scale(1.22) translate3d(1%, 1%, 0)','scale(1.06) translate3d(0, 0, 0)'],
tilt:['scale(1.16) translate3d(0, 3.5%, 0)','scale(1.16) translate3d(0, -3%, 0)'],
orbit:['scale(1.1) rotate(-1.2deg) translate3d(1%, 0, 0)','scale(1.18) rotate(.5deg) translate3d(-1%, -1%, 0)'],
drift:['scale(1.18) rotate(.8deg) translate3d(-2%, 1.5%, 0)','scale(1.07) rotate(-.3deg) translate3d(2%, -1%, 0)']
};
let si=0,timer=null,visible=true;
const load=s=>{
const src=$('source',s),img=$('img',s);
if(src&&src.dataset.srcset){src.srcset=src.dataset.srcset;delete src.dataset.srcset;}
if(img&&img.dataset.src){img.src=img.dataset.src;delete img.dataset.src;}
return img;
};
const move=(s,loop)=>{
if(reduced||!s)return null;
const[a,b]=MOVES[s.dataset.move]||MOVES.push;
const anim=$('img',s).animate([{transform:a},{transform:b}],loop
?{duration:18000,easing:'ease-in-out',iterations:Infinity,direction:'alternate'}
:{duration:DWELL+2600,easing:'cubic-bezier(.33, 0, .4, 1)',fill:'both'});
if(!visible||document.hidden||Motion.paused)anim.pause();
return anim;
};
const setPlace=name=>{
if(!place||!name)return;
const old=place.lastElementChild;
const n=document.createElement('span');n.innerHTML=name;
if(old&&old.textContent===n.textContent)return;
if(reduced||!old){place.textContent='';place.appendChild(n);return;}
n.className='in';place.appendChild(n);old.className='out';
requestAnimationFrame(()=>requestAnimationFrame(()=>{n.className='';}));
setTimeout(()=>{if(old.parentNode)old.remove();},700);
};
const manual=hero.hasAttribute('data-manual');
let pending=-1;
const next=async target=>{
const to=target==null?(si+1)%scenes.length:target;
if(to===si||to<0||to>=scenes.length)return;
pending=to;
const s=scenes[to],img=load(s);
try{if(img&&!img.complete)await img.decode();}catch(e){}
if(pending!==to)return;
const from=scenes[si];si=to;
s._cam=move(s,manual);
if(!reduced){
const out=from.animate([{transform:'scale(1)'},{transform:'scale(1.24)'}],{duration:1500,easing:'cubic-bezier(.5, 0, .8, .4)',fill:'forwards'});
s.animate([{transform:'scale(1.16)'},{transform:'scale(1)'}],{duration:1600,easing:'cubic-bezier(.16, 1, .3, 1)'});
setTimeout(()=>{out.cancel();if(from._cam&&!from.classList.contains('is-on')){from._cam.cancel();from._cam=null;}},1800);
}
s.classList.add('is-on');from.classList.remove('is-on');
setPlace(s.dataset.place||'');
if(!manual)load(scenes[(to+1)%scenes.length]);
};
IC.pageHero={show:i=>next(i),scenes};
const start=()=>{if(manual||reduced||scenes.length<2||timer||!visible||document.hidden||Motion.paused)return;timer=setInterval(next,DWELL);};
const stop=()=>{clearInterval(timer);timer=null;};
scenes[0]._cam=move(scenes[0],scenes.length<2||manual);
if(scenes.length>1){
setPlace(scenes[0].dataset.place||'');
if(!manual){
const warm=()=>load(scenes[1]);
if('requestIdleCallback'in window)requestIdleCallback(warm,{timeout:2500});else setTimeout(warm,1500);
}
}
let tx=0,ty=0,cx=0,cy=0,raf=0,rect=null;
const apply=()=>{
raf=0;
cx+=(tx-cx)*.07;cy+=(ty-cy)*.07;
const sc=Math.min(1,Math.max(0,window.scrollY/(hero.offsetHeight||1)));
rig.style.setProperty('--rx',(-cx*20).toFixed(2)+'px');
rig.style.setProperty('--ry',(-cy*12+sc*70).toFixed(2)+'px');
rig.style.setProperty('--rz',(1+sc*.1).toFixed(4));
if(Math.abs(tx-cx)>.002||Math.abs(ty-cy)>.002)raf=requestAnimationFrame(apply);
};
const kick=()=>{if(!raf)raf=requestAnimationFrame(apply);};
if(!reduced){
if(window.matchMedia('(pointer: fine)').matches){
hero.addEventListener('pointerenter',()=>{rect=hero.getBoundingClientRect();});
hero.addEventListener('pointermove',e=>{
if(e.pointerType!=='mouse')return;
const r=rect||(rect=hero.getBoundingClientRect());
tx=((e.clientX-r.left)/r.width)*2-1;ty=((e.clientY-r.top)/r.height)*2-1;kick();
},{passive:true});
hero.addEventListener('pointerleave',()=>{tx=0;ty=0;rect=null;kick();});
}
window.addEventListener('scroll',()=>{rect=null;if(window.scrollY<hero.offsetHeight*1.3)kick();},{passive:true});
}
const pause=()=>{stop();scenes.forEach(s=>s._cam&&s._cam.pause());};
const play=()=>{if(Motion.paused)return;scenes.forEach(s=>s._cam&&s.classList.contains('is-on')&&s._cam.play());start();};
if('IntersectionObserver'in window)new IntersectionObserver(en=>{visible=en[0].isIntersecting;visible?play():pause();},{threshold:.05}).observe(hero);
document.addEventListener('visibilitychange',()=>(document.hidden?pause():play()));
Motion.on(p=>(p?pause():visible&&!document.hidden&&play()));
Motion.button(hero,'on-photo ph-motion');
start();
if(!reduced)$$('.page-hero-stats strong',hero).forEach(el=>{
const txt=el.textContent.trim();if(!/^\d+$/.test(txt)||+txt<3)return;
const n=+txt,t0=performance.now()+450,dur=1100;
el.textContent='0';
const tick=now=>{const k=Math.min(1,Math.max(0,(now-t0)/dur));el.textContent=String(Math.round(n*(1-Math.pow(1-k,3))));if(k<1)requestAnimationFrame(tick);};
requestAnimationFrame(tick);
setTimeout(()=>{el.textContent=txt;},2000);
});
}
function initTravelogue(){
const hero=$('.hero-tl');if(!hero)return;
const rig=$('#tlRig',hero),deck=$('#tlDeck',hero),stack=$('#tlStack',hero),prints$=$('.tl-prints',hero),leak=$('.tl-leak',hero);
const scenes=$$('.scene',rig),prints=$$('.print',deck),thumbs=$$('#tlThumbs button',hero),chips=$$('#tlChips button',hero);
const place=$('#tlPlace',hero),thumbRow=$('#tlThumbs',hero),chipRow=$('#tlChips',hero);
if(!rig||!deck||!scenes.length||!prints.length)return;
const DWELL=3000,FAR=4,L=scenes.length;
hero.style.setProperty('--tl-dwell',DWELL+'ms');
const fine=window.matchMedia('(pointer: fine)').matches;
const MOVES={
push:['scale(1.06) translate3d(0, 0, 0)','scale(1.2) translate3d(-1.5%, 1%, 0)'],
dolly:['scale(1.04) translate3d(0, 1%, 0)','scale(1.3) translate3d(0, -1%, 0)'],
panR:['scale(1.16) translate3d(-4%, 0, 0)','scale(1.16) translate3d(4%, -.5%, 0)'],
pull:['scale(1.24) translate3d(1%, 1%, 0)','scale(1.07) translate3d(0, 0, 0)'],
tilt:['scale(1.18) translate3d(0, 4%, 0)','scale(1.18) translate3d(0, -3.5%, 0)'],
panL:['scale(1.16) translate3d(4%, 0, 0)','scale(1.16) translate3d(-4%, .5%, 0)'],
orbit:['scale(1.1) rotate(-1.4deg) translate3d(1%, 0, 0)','scale(1.2) rotate(.6deg) translate3d(-1%, -1%, 0)'],
drift:['scale(1.2) rotate(1deg) translate3d(-2%, 2%, 0)','scale(1.08) rotate(-.4deg) translate3d(2%, -1%, 0)']
};
let si=0,lastScene=0,order=prints.map((_,k)=>k),timer=null,busy=false;
let visible=true,hovering=false,focused=false,dragging=false;
const loadScene=s=>{
const src=$('source',s),img=$('img',s);
if(src&&src.dataset.srcset){src.srcset=src.dataset.srcset;delete src.dataset.srcset;}
if(img&&img.dataset.src){img.src=img.dataset.src;delete img.dataset.src;}
return img;
};
const loadPrint=p=>{
const img=$('img',p);if(!img||!img.dataset.src)return;
if(img.dataset.srcset){img.sizes=img.dataset.sizes||'';img.srcset=img.dataset.srcset;delete img.dataset.srcset;}
img.src=img.dataset.src;delete img.dataset.src;
};
let near=1;
const warmPile=()=>{near=FAR;order.forEach((k,d)=>{if(d<=FAR)loadPrint(prints[k]);});};
const camera=s=>{
if(reduced||!s)return;
if(s._cam)s._cam.cancel();
const[a,b]=MOVES[s.dataset.move]||MOVES.push;
s._cam=$('img',s).animate([{transform:a},{transform:b}],{duration:DWELL+2600,easing:'cubic-bezier(.33, 0, .4, 1)',fill:'both'});
if(!visible||document.hidden||Motion.paused)s._cam.pause();
};
const setPlace=name=>{
if(!place||!name)return;
const old=place.lastElementChild;
if(old&&old.textContent===name)return;
const n=document.createElement('span');n.textContent=name;
if(reduced||!old){place.textContent='';place.appendChild(n);return;}
n.className='in';place.appendChild(n);old.className='out';
requestAnimationFrame(()=>requestAnimationFrame(()=>{n.className='';}));
setTimeout(()=>{if(old.parentNode)old.remove();},700);
};
const center=(row,el)=>requestAnimationFrame(()=>{if(row&&el&&row.scrollWidth>row.clientWidth)row.scrollTo({left:el.offsetLeft-row.clientWidth/2+el.offsetWidth/2,behavior:reduced?'auto':'smooth'});});
const markChip=()=>{
chips.forEach((c,k)=>{c.setAttribute('aria-pressed',String(k===si));c.classList.remove('run');});
const c=chips[si];if(!c)return;
requestAnimationFrame(()=>requestAnimationFrame(()=>{if(timer&&chips[si]===c)c.classList.add('run');}));
center(chipRow,c);
};
let switching=false;
const showScene=async(n,manual)=>{
const to=((n%L)+L)%L,now=performance.now();
if(to===si||switching||(!manual&&now-lastScene<1300))return;
lastScene=now;switching=true;
const s=scenes[to],img=loadScene(s);
try{if(img&&!img.complete)await img.decode();}catch(e){}
switching=false;
const from=scenes[si];si=to;
camera(s);
if(!reduced){
const out=from.animate([{transform:'scale(1)'},{transform:'scale(1.28)'}],{duration:1200,easing:'cubic-bezier(.5, 0, .8, .4)',fill:'forwards'});
s.animate([{transform:'scale(1.18)'},{transform:'scale(1)'}],{duration:1300,easing:'cubic-bezier(.16, 1, .3, 1)'});
setTimeout(()=>out.cancel(),1400);
if(leak){leak.classList.remove('flash');void leak.offsetWidth;leak.classList.add('flash');}
}
s.classList.add('is-on');from.classList.remove('is-on');
setTimeout(()=>{if(from._cam&&!from.classList.contains('is-on')){from._cam.cancel();from._cam=null;}},1400);
setPlace(s.dataset.place?s.dataset.place.replace(/&amp;/g,'&'):'');
markChip();
loadScene(scenes[(to+1)%L]);loadScene(scenes[(to+2)%L]);
};
const layout=()=>{
order.forEach((k,d)=>{
const p=prints[k];
p.style.setProperty('--d',Math.min(d,FAR));
p.style.setProperty('--o',d<FAR?1:0);
p.classList.toggle('is-top',d===0);
p.setAttribute('aria-hidden',d===0?'false':'true');
const z=$('.print-zoom',p);if(z)z.tabIndex=d===0?0:-1;
if(d<=Math.max(near,1))loadPrint(p);
});
const top=order[0];
thumbs.forEach((b,k)=>b.setAttribute('aria-current',String(k===top)));
center(thumbRow,thumbs[top]);
};
const undeal=()=>prints.forEach(p=>p.classList.remove('deal'));
const focusIn=()=>{
if(reduced)return;
const p=prints[order[0]];p.classList.remove('focus-in');void p.offsetWidth;p.classList.add('focus-in');
};
const throwTop=(dir,from)=>new Promise(res=>{
undeal();
const p=prints[order[0]];
let settled=false,anim=null;
const settle=()=>{
if(settled)return;settled=true;
p.style.transition='none';p.style.transform='';p.style.setProperty('--glare','0');
order.push(order.shift());layout();
if(anim)anim.cancel();
void p.offsetWidth;p.style.transition='';
focusIn();res();
};
if(reduced){settle();return;}
const start=from||getComputedStyle(p).transform;
anim=p.animate([
{transform:start==='none'?'none':start,opacity:1},
{transform:`translate3d(${dir*128}%, -16%, 0) rotate(${dir*19}deg)`,opacity:0}
],{duration:520,easing:'cubic-bezier(.45, 0, .8, .35)',fill:'forwards'});
anim.onfinish=settle;
setTimeout(settle,700);
});
const bringBack=()=>{
undeal();
const k=order.pop();order.unshift(k);
const p=prints[k];loadPrint(p);
if(reduced){layout();return;}
p.style.transition='none';layout();
const a=p.animate([{transform:'translate3d(-128%, -16%, 0) rotate(-19deg)',opacity:0},{opacity:1,offset:.5}],{duration:620,easing:'cubic-bezier(.16, 1, .3, 1)'});
a.onfinish=a.oncancel=()=>{p.style.transition='';};
focusIn();
};
const next=async(dir=1,from,auto)=>{
if(busy)return;
if(auto){const im=loadScene(scenes[(si+1)%L]);if(im&&!(im.complete&&im.naturalWidth))return;}
busy=true;
showScene(si+1);
await throwTop(dir,from);
busy=false;
};
const prev=()=>{if(busy)return;showScene(si-1);bringBack();};
const jump=k=>{
const pos=order.indexOf(k);if(pos<=0||busy)return;
undeal();order=order.slice(pos).concat(order.slice(0,pos));layout();focusIn();showScene(si+1);
};
const lightboxOpen=()=>!!$('.lightbox.open');
const held=()=>hovering||focused||dragging||!visible||document.hidden||lightboxOpen()||Motion.paused;
const stop=()=>{clearInterval(timer);timer=null;chips.forEach(c=>c.classList.remove('run'));};
const start=()=>{
if(reduced||timer||held())return;
timer=setInterval(()=>{if(lightboxOpen())return;next(1,undefined,true);markChip();},DWELL);
markChip();
};
const restart=()=>{stop();start();};
const nb=$('#tlNext',hero),pb=$('#tlPrev',hero);
if(nb)nb.addEventListener('click',()=>{next(1);restart();});
if(pb)pb.addEventListener('click',()=>{prev();restart();});
thumbs.forEach((b,k)=>b.addEventListener('click',()=>{jump(k);restart();}));
chips.forEach((b,k)=>b.addEventListener('click',()=>{showScene(k,true);restart();}));
stack.addEventListener('keydown',e=>{
if(e.key==='ArrowRight'){e.preventDefault();next(1);restart();}
else if(e.key==='ArrowLeft'){e.preventDefault();prev();restart();}
});
prints$.addEventListener('focusin',e=>{if(e.target.matches(':focus-visible')){focused=true;stop();}});
prints$.addEventListener('focusout',e=>{if(!prints$.contains(e.relatedTarget)){focused=false;start();}});
prints$.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){hovering=true;stop();}});
prints$.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'){hovering=false;start();}});
deck.addEventListener('click',e=>{
const z=e.target.closest('.print-zoom');if(!z)return;
e.stopPropagation();stop();
if(typeof openLightbox==='function')openLightbox(z.dataset.lg,(z.dataset.title||'').replace(/&rsquo;/g,'\u2019'));
});
document.addEventListener('keyup',e=>{if(e.key==='Escape')setTimeout(start,50);});
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('.lightbox'))setTimeout(start,50);});
if(fine&&!reduced){
stack.addEventListener('pointermove',e=>{
if(e.pointerType!=='mouse')return;
const p=prints[order[0]],r=p.getBoundingClientRect();
p.style.setProperty('--gx',(((e.clientX-r.left)/r.width)*100).toFixed(1)+'%');
p.style.setProperty('--gy',(((e.clientY-r.top)/r.height)*100).toFixed(1)+'%');
p.style.setProperty('--glare','1');
});
stack.addEventListener('pointerleave',()=>prints.forEach(p=>p.style.setProperty('--glare','0')));
}
let drag=null;
deck.addEventListener('pointerdown',e=>{
const p=e.target.closest('.print');
if(!p||e.target.closest('.print-zoom')||!p.classList.contains('is-top')||busy||(e.button!==undefined&&e.button!==0))return;
const now=performance.now();
drag={p,x:e.clientX,y:e.clientY,dx:0,dy:0,moved:false,vx:0,lx:e.clientX,lt:now,r:parseFloat(p.style.getPropertyValue('--r'))||0};
try{p.setPointerCapture(e.pointerId);}catch(err){}
});
deck.addEventListener('pointermove',e=>{
if(!drag)return;
const dx=e.clientX-drag.x,dy=e.clientY-drag.y;
if(!drag.moved&&Math.hypot(dx,dy)<6)return;
if(!drag.moved){drag.moved=true;dragging=true;stop();undeal();drag.p.classList.add('is-dragging');}
const now=performance.now();
drag.vx=(e.clientX-drag.lx)/Math.max(1,now-drag.lt);drag.lx=e.clientX;drag.lt=now;
drag.dx=dx;drag.dy=dy;
drag.p.style.transform=`translate3d(${dx}px, ${dy*.5}px, 0) rotate(${drag.r+dx/14}deg)`;
});
const endDrag=e=>{
if(!drag)return;
const d=drag;drag=null;
d.p.classList.remove('is-dragging');
if(!d.moved){if(e.type==='pointerup'){next(1);restart();}return;}
dragging=false;
if(Math.abs(d.dx)>110||Math.abs(d.vx)>.6){
const from=d.p.style.transform;d.p.style.transform='';
next(Math.sign(d.dx||d.vx)||1,from);
}else d.p.style.transform='';
start();
};
deck.addEventListener('pointerup',endDrag);
deck.addEventListener('pointercancel',endDrag);
deck.addEventListener('dragstart',e=>e.preventDefault());
let tx=0,ty=0,cx=0,cy=0,raf=0,rect=null;
const apply=()=>{
raf=0;
cx+=(tx-cx)*.07;cy+=(ty-cy)*.07;
const s=Math.min(1,Math.max(0,window.scrollY/(hero.offsetHeight||1)));
rig.style.setProperty('--rx',(-cx*22).toFixed(2)+'px');
rig.style.setProperty('--ry',(-cy*14+s*90).toFixed(2)+'px');
rig.style.setProperty('--rz',(1+s*.12).toFixed(4));
deck.style.setProperty('--ty',(cx*9).toFixed(2)+'deg');
deck.style.setProperty('--tx',(-cy*7).toFixed(2)+'deg');
deck.style.setProperty('--sy',(-s*64).toFixed(1)+'px');
if(Math.abs(tx-cx)>.002||Math.abs(ty-cy)>.002)raf=requestAnimationFrame(apply);
};
const kick=()=>{if(!raf)raf=requestAnimationFrame(apply);};
if(!reduced){
if(fine){
hero.addEventListener('pointerenter',()=>{rect=hero.getBoundingClientRect();});
hero.addEventListener('pointermove',e=>{
if(e.pointerType!=='mouse')return;
const r=rect||(rect=hero.getBoundingClientRect());
tx=((e.clientX-r.left)/r.width)*2-1;ty=((e.clientY-r.top)/r.height)*2-1;kick();
},{passive:true});
hero.addEventListener('pointerleave',()=>{tx=0;ty=0;rect=null;kick();});
window.addEventListener('resize',()=>{rect=null;},{passive:true});
}
window.addEventListener('scroll',()=>{rect=null;if(window.scrollY<hero.offsetHeight*1.3)kick();},{passive:true});
}
const pauseAll=()=>{stop();scenes.forEach(s=>s._cam&&s._cam.pause());};
const playAll=()=>{if(Motion.paused)return;scenes.forEach(s=>s._cam&&s.classList.contains('is-on')&&s._cam.play());start();};
if('IntersectionObserver'in window){
new IntersectionObserver(en=>{visible=en[0].isIntersecting;visible?playAll():pauseAll();},{threshold:.05}).observe(hero);
}
document.addEventListener('visibilitychange',()=>(document.hidden?pauseAll():playAll()));
Motion.on(p=>(p?pauseAll():visible&&!document.hidden&&playAll()));
Motion.button($('.tl-reel',hero),'on-photo tl-motion',true);
prints.forEach(p=>p.addEventListener('animationend',ev=>{if(ev.animationName==='tlDeal')p.classList.remove('deal');}));
layout();camera(scenes[0]);setPlace((scenes[0].dataset.place||'').replace(/&amp;/g,'&'));
const warm=()=>{warmPile();loadScene(scenes[1]);loadScene(scenes[2%L]);};
const idle=()=>('requestIdleCallback'in window?requestIdleCallback(warm,{timeout:2500}):setTimeout(warm,800));
if(document.readyState==='complete')idle();else window.addEventListener('load',idle,{once:true});
start();
}
