pkg?`<div class="row"><span>Package</span><strong>${esc(pkg)}</strong></div>`:'',
`<div class="row"><span>${amt?'Estimated total':'Amount'}</span><strong class="${amt?'big':''}">${amt?esc(amt):'Confirmed on your official invoice'}</strong></div>`
