(()=>{
const SEL='.svc-icon, .pillar .ic, .contact-card .ic, .choice label .ic, .inq-tab .ic, .inq-tab .lock, .svc-head .ic, .float-card .ic, .mv-card .ic, .nm-ic, .guide-ic, .ck-ic, .fare-ic, .plan-ic, .tk-ic, .nb-ic';
const HOST='a, label, button, .svc-card, .pillar, .contact-card, .mv-card, .float-card, .guide-card, .ck-card, .tk, .fare, .plan-row, .svc-head, .nm-item, .inq-tab, li';
const IDLE=['icBob','icSway','icBreathe','icTilt'];
const SHAPES='path, circle, rect, line, polyline, polygon, ellipse';
const root=document.documentElement;
let n=0,batch=0,batchTimer=0,seen,onScreen;
const done=new WeakSet();
function prep(el){
if(done.has(el))return;
done.add(el);el.classList.remove('ic-in','ic-on');
const k=n++;
el.classList.add('ic-fx');
if(el.classList.contains('lock'))el.classList.add('ic-small');
el.style.setProperty('--ic-idle',IDLE[k%IDLE.length]);
el.style.setProperty('--ic-dur',(3+(k*7%10)/5).toFixed(1)+'s');
el.style.setProperty('--ic-ring',(3.6+(k*3%7)/3).toFixed(1)+'s');
const svg=el.querySelector(':scope > svg');
if(svg){
let p=0;
svg.querySelectorAll(SHAPES).forEach(s=>{
const cs=getComputedStyle(s);
if(cs.stroke==='none'||parseFloat(cs.strokeWidth)===0)return;
s.setAttribute('pathLength','1');s.style.setProperty('--ic-p',p++);
});
}
const host=el.closest(HOST);
if(host)host.classList.add('ic-host');
if(el.classList.contains('nm-ic')){
const items=[...el.closest('.nm-list, .nav-menu, nav').querySelectorAll('.nm-ic')];
el.style.setProperty('--ic-i',items.indexOf(el));
el.classList.add('ic-in','ic-on');
return;
}
if(!seen){el.classList.add('ic-in','ic-on');return;}
seen.observe(el);onScreen.observe(el);
}
function scan(node){
if(!(node instanceof Element))return;
if(node.matches(SEL))prep(node);
node.querySelectorAll(SEL).forEach(prep);
}
function start(){
if('IntersectionObserver'in window){
root.classList.add('ic-anim');
seen=new IntersectionObserver(es=>es.forEach(en=>{
if(!en.isIntersecting)return;
en.target.style.setProperty('--ic-i',batch++%8);
clearTimeout(batchTimer);batchTimer=setTimeout(()=>{batch=0;},160);
en.target.classList.add('ic-in');seen.unobserve(en.target);
}),{rootMargin:'0px 0px -4% 0px',threshold:0});
onScreen=new IntersectionObserver(es=>es.forEach(en=>en.target.classList.toggle('ic-on',en.isIntersecting)));
}
scan(document.body);
let queued=[],raf=0;
new MutationObserver(ms=>{
ms.forEach(m=>m.addedNodes.forEach(x=>queued.push(x)));
if(!raf)raf=requestAnimationFrame(()=>{raf=0;const q=queued;queued=[];q.forEach(scan);});
}).observe(document.body,{childList:true,subtree:true});
}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start):start();
})();

